"""check_menu.py -- verify the CLI tables and callbacks against cli_commands.txt.

Checks:
  1. cli_commands.txt parses and obeys every rule of MenuBuilder_hierarchical.md
     (gen_menu.load raises on a violation).
  2. menu_table.c, menu_commands.h and MenuDocumentation.md are byte-identical
     to a fresh generation from the .txt (no hand edits, no stale output).
  3. Every FUNCTION of the .txt is defined exactly once in cli_commands.c with
     the callback signature, and cli_commands.c defines no callback-shaped
     public function that the .txt does not name.
  4. Every function in menu.c and cli_commands.c carries a Doxygen block.
Prints one anchored line: CHECK PASS: ... or CHECK FAIL: ...; exit 0 / 1.
"""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import gen_menu  # noqa: E402


def read(name):
    """File text with line ends normalized to LF (a checkout may carry CRLF
    through core.autocrlf; the generator writes LF)."""
    with open(os.path.join(HERE, name), encoding="utf-8", newline="") as fh:
        return fh.read().replace("\r\n", "\n")


def function_defs(text):
    """Names of functions defined at file scope (a line starting with a type, an
    identifier and '(' and the body brace on the next line)."""
    pat = re.compile(r"^(?:static\s+)?(?:const\s+)?[A-Za-z_][A-Za-z0-9_ \*]*?\b([A-Za-z_][A-Za-z0-9_]*)\s*\([^;]*\)\s*\n\{",
                     re.M)
    return [m.group(1) for m in pat.finditer(text)], pat


def main():
    errors = []
    try:
        model = gen_menu.load()
    except gen_menu.InputError as e:
        print(f"CHECK FAIL: cli_commands.txt: {e}")
        return 1

    for name, fn in gen_menu.OUTPUTS.items():
        want = fn(model)
        try:
            have = read(name)
        except FileNotFoundError:
            errors.append(f"{name} missing")
            continue
        if have != want:
            errors.append(f"{name} differs from a fresh generation (run python cli/gen_menu.py)")

    cmds_c = read("rtlnet_commands.c")
    names, _ = function_defs(cmds_c)
    funcs = [c["func"] for c in model["commands"] if c["func"] != "-"]
    for f in funcs:
        n = len(re.findall(rf"^int {re.escape(f)}\(const MenuCommandContext \*c\)\s*\{{", cmds_c, re.M))
        if n != 1:
            errors.append(f"callback {f} defined {n} times in cli_commands.c (want 1, signature "
                          f"'int {f}(const MenuCommandContext *ctx)')")
    for m in re.finditer(r"^int (cli_[a-z0-9_]+)\(const MenuCommandContext \*c\)", cmds_c, re.M):
        if m.group(1) not in funcs:
            errors.append(f"cli_commands.c defines callback {m.group(1)} that cli_commands.txt does not name")

    for src in ("menu.c", "rtlnet_commands.c"):
        text = read(src)
        _, pat = function_defs(text)
        for m in pat.finditer(text):
            before = text[:m.start()].rstrip()
            if not before.endswith("*/") or "/**" not in before[before.rfind("/*") - 1:]:
                errors.append(f"{src}: function {m.group(1)} has no Doxygen /** */ block")

    if errors:
        for e in errors:
            print(f"check_menu: {e}")
        print(f"CHECK FAIL: {len(errors)} problem(s)")
        return 1
    print(f"CHECK PASS: tables match cli_commands.txt ({len(model['commands'])} commands, "
          f"{len(funcs)} callbacks, {len(model['keywords'])} keyword groups)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
